      .height(50)
      .clipShape(new CircleShape({
        width: 50,
        height: 50
      }))
      .justifyContent(FlexAlign.Center)
      .backgroundColor(Color.Transparent)
      // 在Navigation标题栏中开启沉浸光感，处于生效范围内，沉浸光感效果生效
      .systemMaterial(new uiMaterial.ImmersiveMaterial({
        style: uiMaterial.ImmersiveStyle.THIN,
      }))
    }
    .alignItems(VerticalAlign.Center)
    .width('100%')
    .padding(16)
  }

  build() {
    Column() {
      Navigation() {
        Column() {
          Row() {
            // 请将$r('app.string.content_area')替换为实际资源文件，在本示例中该资源文件的value值为"内容区"
            Text($r('app.string.content_area'))

            Blank()

            Column() {
              SymbolGlyph($r('sys.symbol.a_3d_square_fill'))
            }
            .width(50)
            .height(50)
            .clipShape(new CircleShape({
              width: 50,
              height: 50
            }))
            .justifyContent(FlexAlign.Center)
            .backgroundColor(Color.Transparent)
            // 在Navigation内容中开启沉浸光感，处于生效范围外，不生效沉浸光感效果
            .systemMaterial(new uiMaterial.ImmersiveMaterial({
              style: uiMaterial.ImmersiveStyle.THIN,
            }))
          }
          .width('100%')
          .padding(16)
          .borderRadius(16)
        }
        .width('100%')
        .height('100%')
        .padding(16)
        .backgroundColor('#FFFFFF')
        .linearGradient({
          angle: 0,
          colors: [
            ['#004AAF', 0.0],
            ['#2787D9', 0.5],
            ['#F0FAFF', 1.0]
          ]
        })
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
      }
      .title(this.NavigationTitle, { barStyle: BarStyle.STACK })
    }.width('100%').height('100%').backgroundColor('#F1F3F5')
  }
}

// 错误写法：不透明背景色会覆盖在材质层之上，导致材质效果不可见
Column() {
  Text('沉浸光感')
}
.width(328)
.height(56)
.borderRadius(28)
.systemMaterial(new uiMaterial.ImmersiveMaterial({
  style: uiMaterial.ImmersiveStyle.THIN,
}))
.backgroundColor(Color.White)
// 推荐写法：将背景色设为透明，确保材质效果可见
Column() {
  Text('沉浸光感')
}
.width(328)
.height(56)
.borderRadius(28)
.backgroundColor(Color.Transparent)
.systemMaterial(new uiMaterial.ImmersiveMaterial({
  style: uiMaterial.ImmersiveStyle.THIN,
}))

// 错误写法：纯不透明颜色遮挡了材质效果
new uiMaterial.ImmersiveMaterial({
  style: uiMaterial.ImmersiveStyle.THIN,
  materialColor: Color.Red, // 不透明，材质滤镜效果被完全遮挡
})

// 推荐写法：使用带透明度的颜色
new uiMaterial.ImmersiveMaterial({
  style: uiMaterial.ImmersiveStyle.THIN,
  materialColor: '#80FF0000', // 带有50%透明度的红色
})

// 关闭材质阴影，使用自定义shadow
new uiMaterial.ImmersiveMaterial({
  style: uiMaterial.ImmersiveStyle.REGULAR,
  applyShadow: false,
})

// 推荐写法：先设置其他属性，再设置systemMaterial
Column() {
  Text('推荐')
}
.width(328)
.height(56)
.borderRadius(28)
.justifyContent(FlexAlign.Center)
.systemMaterial(new uiMaterial.ImmersiveMaterial({
  style: uiMaterial.ImmersiveStyle.REGULAR,
}))

// 材质渲染区域与组件可视区域不一致示例
Row() {
  Text('Checkbox组件：')
    .fontColor(Color.Black)
  Checkbox()
    .width(40)
    .height(40)
    .borderWidth(1)
    .borderColor(Color.Blue)
    .systemMaterial(new uiMaterial.ImmersiveMaterial({
      style: uiMaterial.ImmersiveStyle.ULTRA_THIN,
      interactive: true
    }))
}
Row() {
  Text('Text组件：')
    .fontColor(Color.Black)
  Text("hello")
    .width(100)
    .height(40)
    .systemMaterial(new uiMaterial.ImmersiveMaterial({
      style: uiMaterial.ImmersiveStyle.ULTRA_THIN,
      interactive: true
    }))
}

// 材质效果的显示层级问题示例
Row() {
  Text('TextArea组件：')
    .fontColor(Color.Black)
  TextArea()
    .width(100)
    .height(40)
    .backgroundColor('#cc999999') // 不建议同时使用沉浸式系统材质和背景色接口
    .systemMaterial(new uiMaterial.ImmersiveMaterial({
      style: uiMaterial.ImmersiveStyle.ULTRA_THIN,
      interactive: true
    }))
}
